import { createPublicKey, verify } from "node:crypto";
import { ModelDownloadError } from "./modelDownloader.js";

/**
 * RedRooster's model mirror: every model LANA Briefs downloads is served from its own R2
 * bucket behind Cloudflare at this address, under immutable versioned keys
 * (`briefs/<kind>/<id>/<version>/<path>`), and checked against the manifest the app pins
 * (`briefsManifest.ts`, generated by `scripts/models/mirror-models.mjs`).
 */
export const MIRROR_BASE = "https://models.lanaai.io";

/**
 * When true, a download whose mirror is unreachable (no connection to it, or an HTTP error
 * from it) is fetched from the original upstream instead (GitHub releases, Hugging Face),
 * still checked against the same pinned SHA-256. Off: LANA Briefs downloads only from
 * models.lanaai.io.
 */
export const UPSTREAM_FALLBACK = false;

export interface BriefsManifestFile {
  /** Relative to the app's models folder, with forward slashes. */
  readonly path: string;
  /** The object key on the mirror. */
  readonly key: string;
  readonly bytes: number;
  readonly sha256: string;
}

export interface BriefsManifestPackage {
  /** A speech package id, or a LANA model's `modelID`. */
  readonly id: string;
  readonly kind: "speech" | "llm";
  /** 12 hex of SHA-256 over the package's sorted "path sha256" lines. */
  readonly version: string;
  readonly license: string;
  /** The file name, or the archive's top-level folder, in the models folder. */
  readonly target: string;
  /** Where the files came from, used only by the fallback. */
  readonly upstream: { readonly url: string; readonly format: "file" | "tar.bz2"; readonly bytes: number; readonly sha256: string };
  readonly files: readonly BriefsManifestFile[];
  /** LICENSE and NOTICE next to the package on the mirror (not downloaded by the app). */
  readonly notices: readonly BriefsManifestFile[];
}

export interface BriefsManifest {
  readonly kind: string;
  readonly version: number;
  readonly base: string;
  readonly packages: readonly BriefsManifestPackage[];
  /** What the iPhone's FluidAudio fetches, mirrored in its Hugging Face registry layout under `base`. */
  readonly hf?: {
    readonly base: string;
    readonly repos: ReadonlyArray<{
      readonly repo: string;
      readonly revision: string;
      readonly commit: string;
      readonly license: string;
      readonly listings: readonly { readonly key: string; readonly bytes: number; readonly sha256: string }[];
      readonly files: readonly { readonly key: string; readonly bytes: number; readonly sha256?: string; readonly gitOid?: string }[];
      readonly notices: readonly { readonly path: string; readonly key: string; readonly bytes: number; readonly sha256: string }[];
    }>;
  };
  /** The iPhone's MLX models (manifest v2), by Hugging Face repo at a pinned commit. The desktop does not download these. */
  readonly mlx?: {
    readonly repos: ReadonlyArray<{
      readonly repo: string;
      readonly commit: string;
      readonly license: string;
      readonly files: readonly BriefsManifestFile[];
      readonly notices: readonly BriefsManifestFile[];
    }>;
  };
  readonly sig?: { readonly alg: string; readonly keyId: string; readonly value: string };
}

export const BRIEFS_MANIFEST_KIND = "lana.briefs.models/v1";

/**
 * Public keys the manifest may be signed with: LANA's release signing key
 * (LANA-AI `infra/lib/release/verify.js`, `lana-release-prod`).
 */
export const BRIEFS_MANIFEST_KEYS: Readonly<Record<string, string>> = {
  "lana-release-prod": "-----BEGIN PUBLIC KEY-----\nMCowBQYDK2VwAyEAr+t483lYkLZOioFuJcKifU8PtwIYliLSzaPgwK4vzAU=\n-----END PUBLIC KEY-----",
};

export function mirrorURL(key: string, base: string = MIRROR_BASE): string {
  return `${base.replace(/\/+$/, "")}/${key.split("/").map(encodeURIComponent).join("/")}`;
}

/**
 * LANA's release-manifest canonical form (LANA-AI `infra/lib/release/canonical-json.js`):
 * sorted keys, arrays in order, primitives through JSON.stringify. The manifest holds only
 * ASCII strings and integers, where this is byte identical to `LanaJSON`.
 */
export function releaseCanonical(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(releaseCanonical).join(",")}]`;
  if (value !== null && typeof value === "object") {
    const record = value as Record<string, unknown>;
    return `{${Object.keys(record).sort().map((key) => `${JSON.stringify(key)}:${releaseCanonical(record[key])}`).join(",")}}`;
  }
  return JSON.stringify(value === undefined ? null : value);
}

/** True when the manifest is the Briefs kind and its Ed25519 signature verifies under a trusted key. */
export function verifyBriefsManifest(manifest: BriefsManifest, keys: Readonly<Record<string, string>> = BRIEFS_MANIFEST_KEYS): boolean {
  const { sig, ...unsigned } = manifest;
  if (sig === undefined || sig.alg !== "Ed25519" || manifest.kind !== BRIEFS_MANIFEST_KIND) return false;
  const pem = keys[sig.keyId];
  if (pem === undefined) return false;
  try {
    return verify(null, Buffer.from(releaseCanonical(unsigned), "utf8"), createPublicKey(pem), Buffer.from(sig.value, "base64"));
  } catch {
    return false;
  }
}

const verified = new WeakMap<BriefsManifest, boolean>();

/** `verifyBriefsManifest`, checked once per manifest object. */
export function isTrustedManifest(manifest: BriefsManifest): boolean {
  let trusted = verified.get(manifest);
  if (trusted === undefined) {
    trusted = verifyBriefsManifest(manifest);
    verified.set(manifest, trusted);
  }
  return trusted;
}

/**
 * The download URL for a manifest key, or "" when the manifest's signature does not verify:
 * nothing named by an unverified manifest is ever downloaded (an empty URL is refused).
 */
export function trustedURL(manifest: BriefsManifest, key: string): string {
  return isTrustedManifest(manifest) ? mirrorURL(key, manifest.base) : "";
}

export class UntrustedManifestError extends Error {
  constructor() {
    super("untrusted_manifest");
    this.name = "UntrustedManifestError";
  }
}

/** The package `id` in the manifest; throws when the app's pinned manifest does not have it. */
export function manifestPackage(manifest: BriefsManifest, id: string): BriefsManifestPackage {
  const found = manifest.packages.find((pkg) => pkg.id === id);
  if (found === undefined) throw new Error(`briefs_manifest_missing(${id})`);
  return found;
}

/**
 * A mirror failure the fallback may route around: no connection (fetch rejects with a
 * TypeError) or an HTTP error. Never a cancel, a short body or a checksum mismatch.
 */
export function isMirrorUnreachable(error: unknown): boolean {
  if (error instanceof ModelDownloadError) return error.code === "http_status";
  return error instanceof TypeError;
}
